import {BRIEF_EXAMPLES,LOCAL_MODEL,currentBrief,exampleMatches} from './change-brief.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
function sourceCard(record,review,{top=false}={}){
 const comparison=`<div class="brief-comparison"><div class="brief-before"><span>v${review.before.number} · ${review.before.time}</span><p>${record.before?esc(record.before):'No earlier entry'}</p></div><div class="brief-after"><span>v${review.after.number} · ${review.after.time}</span><p>${esc(record.after)}</p></div></div>`;
 return `<article class="brief-source ${top?'brief-top-match':''}" data-dom-key="source-${record.id}"><div class="brief-source-head"><span>${record.patient==='All'?'HANDOFF':`ROOM ${record.patient}`}</span><span>${esc(record.field)}</span></div><h3>${esc(record.name)}</h3>${top?comparison:`<details class="brief-evidence"><summary>Compare versions<span>v${review.before.number} → v${review.after.number}</span></summary>${comparison}</details>`}${record.patientId?`<button class="button text small brief-source-link" data-action="brief-source" data-patient="${record.patientId}" data-version="${review.after.id}">Open patient in v${review.after.number} ${arrow}</button>`:''}</article>`;
}
export function briefBody(review,{mode='demo',example='owner',query='',runtime,showAll=false,sampleHref='/shift?scene=assist&screen=detail&brief=1&briefmode=local'}={}){
 if(!review)return `<div class="brief-welcome"><span class="brief-welcome-label">ON-DEVICE AI</span><h3>Find the change behind your question.</h3><p>Ask about an owner, an expected time or an added note. Local AI finds the related change and keeps the source beside it.</p><div class="brief-welcome-context"><strong>Your handoff is not ready for a comparison yet.</strong><p>Two submitted versions, both readable by this colleague, are needed. You can try the complete workflow in a separate fictional sample.</p></div><a class="button primary" href="${esc(sampleHref)}" target="_blank" rel="noopener">Try AI on a sample <span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a><p class="small-note">Your saved workspace stays in this tab. Model loading is optional and starts only when you choose Load model &amp; search.</p></div>`;
 const busy=['loading','searching','removing'].includes(runtime.phase),valid=currentBrief(runtime.result,review);
 const stale=runtime.result&&!valid;
 const result=mode==='demo'?exampleMatches(review,example):valid?runtime.result.matches:null;
 const matched=(result||[]).map(m=>review.records.find(c=>c.id===m.id)).filter(Boolean);
 const rest=review.records.filter(c=>!matched.some(m=>m.id===c.id));
 // Keep the result node through ordinary rerenders; a new question or example
 // gets its own entrance without replaying when a source disclosure is opened.
 const resultKey=[mode,review.before.id,review.after.id,mode==='demo'?example:runtime.result?.query,...(result||[]).map(m=>m.id)].join(':');
 const showStatus=mode==='local'&&runtime.message&&runtime.phase!=='complete';
 return `<div class="brief-scope"><strong>v${review.before.number} <span aria-hidden="true">→</span> v${review.after.number}</strong><span>${review.records.length} change${review.records.length!==1?'s':''} · ${review.roomCount} room${review.roomCount!==1?'s':''}</span></div>
 <div class="brief-modes" role="group" aria-label="Brief mode"><button type="button" data-action="brief-mode" data-value="demo" aria-pressed="${mode==='demo'}">Guided demo</button><button type="button" data-action="brief-mode" data-value="local" aria-pressed="${mode==='local'}">On-device AI</button></div>
 ${mode==='demo'?`<p class="brief-disclosure">Prepared matches · no model is running</p><div class="brief-examples" aria-label="Prepared example questions">${BRIEF_EXAMPLES.map(e=>`<button data-action="brief-example" data-value="${e.id}" aria-pressed="${example===e.id}" aria-label="${esc(e.label)}">${e.id==='owner'?'Owner':e.id==='time'?'Expected time':'Added note'}</button>`).join('')}</div>`:
 `<form data-form="brief-search" class="brief-search" aria-busy="${busy}"><label class="field-label" for="brief-query">Your question <span>In English</span></label><textarea id="brief-query" name="query" rows="2" maxlength="180" required placeholder="Who took over the family update?">${esc(query)}</textarea><div class="brief-search-actions"><button class="button primary" type="submit" ${busy||!review.records.length?'disabled':''}>${busy?runtime.phase==='loading'?'Loading model…':runtime.phase==='removing'?'Removing model…':'Searching…':runtime.loaded?'Search changes':'Load model & search'} ${busy?'':arrow}</button>${busy&&runtime.phase!=='removing'?'<button class="button secondary" type="button" data-action="brief-stop">Stop</button>':''}</div></form>
 <p class="brief-privacy">${runtime.loaded?'Model ready':'About 50 MB on first use'} · Questions stay on this device.</p>
 ${showStatus?`<div class="brief-runtime-status ${runtime.phase==='error'?'brief-error':''}" role="status">${busy?'<span class="brief-loading" aria-hidden="true"></span>':''}<div><p>${esc(runtime.message)}</p>${runtime.progress!==null&&busy?`<label>Current file<progress max="100" value="${runtime.progress}">${runtime.progress}%</progress></label>`:''}</div></div>`:''}`}
 ${stale&&mode==='local'?'<div class="inline-note brief-stale">The version comparison changed. Search again to update the matches.</div>':''}
 ${result?`<section class="brief-results" data-dom-key="brief-result-${esc(resultKey)}" aria-label="${mode==='demo'?'Prepared example result':'Local search results'}"><div class="brief-results-label"><h3 tabindex="-1" id="brief-result-heading">${matched.length?'Matching change':'No close source match'}</h3><span>${mode==='demo'?'Guided example':'On this device'}</span></div>${matched.length?sourceCard(matched[0],review,{top:true}):'<p class="brief-no-match">Try a more specific question, or read all changes below. The search does not answer beyond these records.</p>'}${matched.length>1?`<details class="brief-related"><summary>${matched.length-1} more match${matched.length>2?'es':''}</summary><div>${matched.slice(1).map(record=>sourceCard(record,review)).join('')}</div></details>`:''}</section>`:''}
 ${rest.length?`<div class="brief-all-heading"><span>${result?'Other changes':'Browse the source'}</span><button class="button text small" data-action="brief-all" aria-expanded="${showAll}">${showAll?'Hide':'Show'} ${rest.length} change${rest.length!==1?'s':''}</button></div>${showAll?`<div class="brief-other">${rest.map(record=>sourceCard(record,review)).join('')}</div>`:''}`:''}
 ${mode==='local'?`<details class="brief-how"><summary>Model &amp; privacy</summary><p>${LOCAL_MODEL.name} ranks up to 64 submitted changes by meaning. It does not write advice, edit records or acknowledge a handoff. Matches can be imperfect; check the original versions.</p><p>First use downloads about 50 MB, including 23 MB of model weights, from Hugging Face and jsDelivr. Questions and records are processed on this device. No API key or paid inference account is needed.</p><p>Files may stay in your browser cache. First use needs a connection; later offline use depends on the retained files. Unloading releases the worker; removing the model clears its cached files when the browser allows it.</p>${runtime.loaded&&!busy?'<div class="brief-model-controls"><button class="button secondary small" data-action="brief-unload">Unload model</button><button class="button text small" data-action="brief-remove">Remove downloaded model</button></div>':''}</details>`:''}
 <p class="brief-boundary">Read-only · Your handoff stays unchanged.</p>`;
}
export function briefCasePreview(){return `<div class="case-ai-preview"><div class="case-ai-preview-top"><span>CHANGE BRIEF</span><strong>v1 → v2</strong></div><p class="case-ai-query">Who took over the family update?</p><div class="case-ai-evidence"><span>ROOM 414 · ACTION OWNER</span><h3>Avery Reid</h3><div><span>v1</span><p>Jordan Lee</p></div><div><span>v2</span><p>Taylor Brooks</p></div><p class="case-ai-source-label">Source: submitted handoff versions</p></div><div class="case-ai-preview-footer"><span>On-device semantic search</span><span>Source-linked result</span></div></div>`;}
